function badge(t){return `<span class="badge ${t.status}">${STATUS[t.status]}</span>`;}
function age(t){return t.wait===null?'未知':t.wait===0?'0 小时':`${t.wait} 小时`;}
function notify(text){const e=$('#notice');e.textContent=text;e.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>{e.hidden=true;},4000);}
