function captureRenderFocus(){
  const active=document.activeElement;
  if(!active||!$('#content').contains(active))return null;
  const key={id:active.id||'',attribute:null,value:null};
  for(const attribute of ['data-stage','data-task','data-asset','data-source','data-remove','data-handoff-task']){
    if(active.hasAttribute(attribute)){key.attribute=attribute;key.value=active.getAttribute(attribute);break;}
  }
  return key;
}
function restoreRenderFocus(key){
  if(!key)return;
  let target=key.id?document.getElementById(key.id):null;
  if(!target&&key.attribute)target=Array.from(document.querySelectorAll('['+key.attribute+']')).find(el=>el.getAttribute(key.attribute)===key.value);
  if(!target){
    if(key.attribute==='data-remove')target=$('#receiver');
    else if(['clearQueue','emptyReset'].includes(key.id))target=$('#taskSearch');
    else if(['allAssets','assetReset'].includes(key.id))target=document.querySelector('[data-asset]')||$('#receiver');
    else target=$('#main');
  }
  target?.focus({preventScroll:true});
}
function render(restoreFocus=true){const focusKey=restoreFocus?captureRenderFocus():null;document.querySelectorAll('[data-page]').forEach(a=>{if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const headings={work:['让每一项工作，都有人接着推进。','先解决等待和阻塞，再把验证过的经验交给下一次工作。'],assets:['把做过的工作，变成可复用的起点。','固定来源与版本，明确授权；在接收项目重新验证和确认。'],handoff:['交接的是可继续工作的上下文。','当前进展、完整依据、未决问题和下一责任人，放在同一份交接包里。']};$('#pageTitle').textContent=headings[state.page][0];$('#pageDescription').textContent=headings[state.page][1];if(state.page==='work')renderWork();else if(state.page==='assets')renderAssets();else renderHandoff();restoreRenderFocus(focusKey);}
function renderWork(){const all=scopedTasks(),rows=visibleTasks();if(!rows.some(t=>t.id===state.selected))state.selected=rows[0]?.id??null;const blocked=count(all,t=>t.status==='blocked'),waiting=count(all,t=>t.status==='waiting'),unknown=count(all,t=>t.wait===null);$('#content').innerHTML=`<div class="attention"><span>进行中的任务 <b>${all.length}</b></span><span class="problem"><b>${blocked}</b> 项受阻</span><span class="wait"><b>${waiting}</b> 项等待接力</span><span class="metric-note">当前筛选下的合成记录 · ${unknown} 项等待起点未知</span></div><section class="flow" aria-label="展示阶段，点击筛选任务">${STAGES.map((s,i)=>{const ts=all.filter(t=>t.stage===s),b=count(ts,t=>t.status==='blocked'),w=count(ts,t=>t.status==='waiting');return `<button class="stage" data-stage="${s}" aria-pressed="${state.stage===s}" aria-label="${s}阶段 ${ts.length} 项任务，点击${state.stage===s?'取消':'应用'}筛选"><span class="stage-title"><span>${String(i+1).padStart(2,'0')} · ${s}</span><span>${i<4?'→':'↺'}</span></span><span class="stage-count"><b>${ts.length}</b><span>项</span></span><span class="stage-caption">${b?`<span class="bad">${b} 受阻</span> · `:''}${w} 等待</span></button>`;}).join('')}</section><div class="workspace-layout"><section class="queue" aria-labelledby="queueTitle"><div class="section-head"><h2 id="queueTitle">下一步行动${state.stage!=='all'?' · '+state.stage:''}</h2><span class="muted">${rows.length} 项 · 人工决定单独保留</span></div><div class="queue-tools"><label class="search"><span class="sr-only" hidden>搜索任务</span><input id="taskSearch" aria-label="搜索任务、负责人或完整正文" type="search" placeholder="搜索任务、负责人或完整正文" value="${esc(state.query)}"></label><select id="statusFilter" aria-label="状态筛选"><option value="all"${state.status==='all'?' selected':''}>全部状态</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}"${state.status===k?' selected':''}>${v}</option>`).join('')}</select>${state.stage!=='all'||state.query||state.status!=='all'?'<button id="clearQueue" class="quiet">清除筛选</button>':''}</div>${rows.length?`<div class="list-head"><span>任务与下一步</span><span>下一责任人</span><span>当前状态</span><span class="wait-column">等待时长</span></div><div class="task-list">${rows.map(t=>`<button class="task-row" data-task="${t.id}" aria-pressed="${state.selected===t.id}"><span><span class="task-key">${t.id} <span class="subtle-divider">/</span> ${PROJECTS[t.project]}</span><span class="task-title">${esc(t.title)}</span><span class="task-action">${esc(t.action)}</span></span><span class="owner">${t.next}<small>${t.role}</small></span><span class="state-column">${badge(t)}</span><span class="waiting-age wait-column">${age(t)}<small>${t.wait===null?'尚未记录起点':t.wait===0?'暂无等待事件':'自等待事件起'}</small></span></button>`).join('')}</div>`:`<div class="empty"><h2>这个范围里没有待办</h2><p>当前筛选匹配 0 条合成记录；不代表全部工作已经完成。</p><button id="emptyReset">查看团队全部任务</button></div>`}<div class="queue-foot"><span>阶段是展示分类，不改变底层任务状态迁移。</span><span>任务 ${rows.length} / ${all.length}</span></div></section><aside id="taskDetail" aria-label="选中任务详情">${detailMarkup(rows.find(t=>t.id===state.selected))}</aside></div>`;document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=state.stage===b.dataset.stage?'all':b.dataset.stage;render();});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.task;render();document.querySelector(`[data-task="${state.selected}"]`)?.focus({preventScroll:true});});$('#taskSearch').oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();$('#taskSearch').focus({preventScroll:true});$('#taskSearch').setSelectionRange(pos,pos);};$('#statusFilter').onchange=e=>{state.status=e.target.value;render();};$('#clearQueue')?.addEventListener('click',()=>{state.stage='all';state.status='all';state.query='';render();});$('#emptyReset')?.addEventListener('click',resetFilters);wireDetail();}
function detailMarkup(t){if(!t)return '<div class="empty"><h2>没有选中的任务</h2><p>清除筛选后，选择一项工作查看下一步与证据。</p></div>';return `<article class="detail"><header class="detail-top"><span class="task-key">${t.id} · ${PROJECTS[t.project]}</span><h2>${esc(t.title)}</h2><div class="labels">${badge(t)}<span class="badge">${t.stage}</span><span class="muted">负责人 ${t.owner}</span></div></header><div class="detail-content"><section class="next-step"><h3>下一步需要做什么</h3><p>${esc(t.action)}</p><div class="next-owner"><span class="avatar">${t.next[0]}</span>${t.next} · ${t.role}</div></section><section class="detail-section"><h3>${t.status==='blocked'?'受阻原因':t.status==='waiting'?'正在等什么':'当前进展'}</h3><p class="muted">${esc(t.reason)}</p><dl><dt>等待时长</dt><dd>${age(t)}${t.wait===null?' · 尚未登记起点':''}</dd><dt>需求版本</dt><dd class="mono">${t.requirement}</dd><dt>候选提交</dt><dd class="mono">${t.commit||'尚未登记固定候选'}</dd></dl></section><section class="detail-section"><h3>验收证据</h3><div class="evidence-item"><span class="evidence-dot ${t.tests?'':'unknown'}"></span><div><strong>技术验证</strong><p>${t.tests?`${t.tests.passed} 通过 · ${t.tests.failed} 失败 · ${t.tests.notRun} 未执行`:'未知 · 未取得本次完整验证回执'}</p></div></div><div class="evidence-item"><span class="evidence-dot pending"></span><div><strong>人工决定</strong><p>${t.human} · 不由机器验证替代</p></div></div><details><summary>查看证据说明与完整来源</summary><p class="raw">${esc(t.evidence)}</p><pre class="raw">${esc(JSON.stringify({kind:'synthetic-example',task:t.id,requirement:t.requirement,commit:t.commit,snapshot:DEMO_NOW,tests:t.tests,human:t.human},null,2))}</pre></details></section><section class="detail-section"><details><summary>展开完整需求原文</summary><p class="raw">${esc(t.body)}</p></details><details><summary>展开完整交接说明</summary><p class="raw">${esc(t.handoff)}</p></details>${state.notes.has(t.id)?`<details open><summary>本页保存的交接草稿</summary><p class="raw">${esc(state.notes.get(t.id))}</p></details>`:''}<div class="detail-actions"><button class="primary" id="draftHandoff">整理交接草稿</button><button id="relatedAssets">查看相关资产</button></div><p class="human-note">此样稿不能确认、合并或关单。后续接入沿用个人身份与具体版本证据。</p></section></div></article>`;}
function wireDetail(){const t=tasks.find(t=>t.id===state.selected);if(!t)return;$('#draftHandoff')?.addEventListener('click',()=>{dialog('整理交接草稿',`<p>任务 ${t.id} · 下一责任人 ${t.next}。保存只保留在当前页面内存，刷新会丢失，不会发送给任何人。</p><label for="handoffNote">完整交接说明</label><textarea id="handoffNote">${esc(state.notes.get(t.id)||t.handoff)}</textarea><p class="muted" id="noteError" role="alert"></p><button class="primary" id="saveNote">保存到本页草稿</button>`);$('#saveNote').onclick=()=>{const body=$('#handoffNote').value;if(!body.trim()){$('#noteError').textContent='请填写交接说明；空白内容不会覆盖现有草稿。';$('#handoffNote').focus();return;}state.notes.set(t.id,body);$('#previewDialog').close();render(false);if(state.page==='work'&&state.selected===t.id)$('#draftHandoff')?.focus({preventScroll:true});notify('交接草稿已保存在本页；未发送、未确认。');};});$('#relatedAssets')?.addEventListener('click',()=>{state.assetQuery=t.asset||'';location.hash='#assets';});}
function renderAssets(){const scoped=scopedTasks(),taskAssetNames=new Set(scoped.map(t=>t.asset).filter(Boolean)),scopeAssets=assets.filter(a=>(state.project==='all'||a.project===state.project||taskAssetNames.has(a.title))&&(state.role==='all'&&state.view==='team'||taskAssetNames.has(a.title))),shown=scopeAssets.filter(a=>!state.assetQuery||a.title===state.assetQuery);$('#content').innerHTML=`<p class="view-note">这里展示 ${shown.length} 项合成资产。${state.assetQuery?`当前关联：${esc(state.assetQuery)}。 <button id="allAssets" class="text-button">查看当前范围全部资产</button>`:''} 项目、角色与“与我相关”共同限定来源或相关任务。</p><div class="workspace-layout"><section class="asset-grid" aria-label="可复用资产">${shown.map(a=>`<article class="asset-card"><span class="badge">${a.kind}</span> <span class="badge ${a.shared?'progress':'waiting'}">${a.shared?'已共享（合成）':'仅本项目'}</span><h2>${a.title}</h2><p>${a.verified}</p><div class="asset-meta">来源 ${a.source}<br>修订 ${a.revision}<br>提交 ${a.commit}</div><p><strong>接收项目需要补齐：</strong>${a.needed}</p><details><summary>展开完整资产说明</summary><p class="raw">${esc(a.body)}</p></details><div class="asset-actions"><button data-asset="${a.id}" class="primary">加入引用草稿</button><button data-source="${a.id}">核对来源</button></div></article>`).join('')||'<div class="empty"><h2>没有匹配资产</h2><p>这个范围中没有可展示的合成资产，不代表已核对可复用性。</p><button id="assetReset">清除全部筛选</button></div>'}</section><aside class="draft-box"><p class="eyebrow">固定版本引用 · 本页草稿</p><h2>为接收项目准备</h2><label for="receiver">接收项目</label><select id="receiver">${Object.entries(PROJECTS).map(([id,name])=>`<option value="${id}"${state.receiver===id?' selected':''}>${name}</option>`).join('')}</select><div id="referenceDraft">${referenceMarkup()}</div><p class="human-note">加入草稿不构成跨项目授权。来源撤销、版本变化和接收项目人工确认，都需要在真实系统中重新核对。</p><button id="previewReferences" class="quiet">预览完整引用包</button></aside></div>`;$('#allAssets')?.addEventListener('click',()=>{state.assetQuery='';render();});$('#assetReset')?.addEventListener('click',()=>{state.assetQuery='';resetFilters();});$('#receiver').onchange=e=>{state.receiver=e.target.value;render();};document.querySelectorAll('[data-asset]').forEach(b=>b.onclick=()=>{const a=assets.find(a=>a.id===b.dataset.asset);if(!a.shared&&a.project!==state.receiver){dialog('这项来源尚未授权跨项目使用',`<p>${a.title} 目前仅限 ${a.source}，而接收项目是 ${PROJECTS[state.receiver]}。</p><p>样稿保留这个阻塞，不自动授予权限。可先在来源项目核对完整内容，后续由授权人员决定共享范围。</p><pre>${esc(a.body)}</pre>`);return;}const key=state.receiver+':'+a.id;if(!state.references.some(r=>r.key===key)){state.references.push({key,receiver:state.receiver,asset:a.id,revision:a.revision,commit:a.commit});notify('已加入本页引用草稿；接收项目仍需独立验证。');}else notify('该固定版本已在本页草稿中，未重复加入。');render();});document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{const a=assets.find(a=>a.id===b.dataset.source);dialog('核对完整来源',`<p>${a.source} · ${a.title}</p><pre>${esc(JSON.stringify(a,null,2))}</pre><p>上方全部字段是合成示例，不是生产授权或确认凭据。</p>`);});wireReferenceRemoval();$('#previewReferences').onclick=()=>{const refs=state.references.filter(r=>r.receiver===state.receiver);dialog('完整引用包 · '+PROJECTS[state.receiver],`<p>${refs.length} 项固定引用草稿；未创建真实引用、未继承任何人工确认。</p><pre>${esc(JSON.stringify({synthetic:true,receiver:state.receiver,references:refs.map(r=>({...r,source:assets.find(a=>a.id===r.asset)})),pending:['核对共享授权与范围','接收项目独立验证适用性','具备权限的人员决定是否采用']},null,2))}</pre>`);};}
function referenceMarkup(){const refs=state.references.filter(r=>r.receiver===state.receiver);return `<p>${refs.length} 项引用草稿 · ${refs.length===0?'尚未选择资产':'人工决定尚未发生'}</p>${refs.length?`<ul>${refs.map(r=>`<li>${assets.find(a=>a.id===r.asset).title}<br><span class="mono">${r.revision}</span> <button class="text-button" data-remove="${r.key}">移出草稿</button></li>`).join('')}</ul>`:'<p>从左侧选择资产，先看版本、共享范围和未验证项。</p>'}`;}
function wireReferenceRemoval(){document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{state.references=state.references.filter(r=>r.key!==b.dataset.remove);render();notify('已从本页草稿移除，真实资产没有变化。');});}
function renderHandoff(){const rows=scopedTasks(),projectLabel=state.project==='all'?'团队全部项目':PROJECTS[state.project],waiting=rows.filter(t=>t.status!=='progress'),withCommit=rows.filter(t=>t.commit),withEvidence=rows.filter(t=>t.tests),known=rows.filter(t=>t.wait!==null);$('#content').innerHTML=`<p class="view-note">${projectLabel} · ${rows.length} 项合成任务的交接视图；交接包不会创建业务签收记录。</p><div class="workspace-layout"><section><article class="handoff-block"><div class="section-head"><h2>这份交接需要留下什么</h2><span class="muted">保留完整原文与来源</span></div><ul class="checklist"><li>当前工作与下一责任人<span>${rows.length} 项任务有下一步和责任人示例；${waiting.length} 项处于等待或受阻。</span></li><li>固定版本与证据<span>${withCommit.length} 项有固定候选；${rows.length-withCommit.length} 项尚未登记候选。${withEvidence.length} 项有合成测试记录。</span></li><li>未决问题与等待起点<span>${rows.length-known.length} 项起点未知；未知不能当成零时长。</span></li><li>适用边界与人工决定<span>来源确认不继承，技术检查不代表客户签收；真实权限需由后端校验。</span></li></ul></article><article class="handoff-block"><h2>优先接力的事项</h2>${waiting.map(t=>`<div class="handoff-line"><span><strong>${t.id} · ${t.title}</strong><small>${t.next} 接续 · ${STATUS[t.status]} · ${age(t)}</small></span><button data-handoff-task="${t.id}">查看任务依据</button></div>`).join('')||'<p class="muted">当前范围内等待或受阻记录为 0；未完成任务仍保留在工作台。</p>'}</article><article class="handoff-block"><h2>交接包完整内容预览</h2><details><summary>展开全部任务、原始需求和证据字段</summary><pre class="handoff-quote mono">${esc(handoffText(rows))}</pre></details></article></section><aside class="draft-box"><p class="eyebrow">接续工作，不只转交文档</p><h2>让接收人知道从哪里开始</h2><p>把当前进展、待决问题、可复用资产和验证依据组合成一份完整包，接收人仍需核对实际适用性。</p><p>本页已保存交接草稿：${rows.filter(t=>state.notes.has(t.id)).length} 项。</p><button id="previewHandoff" class="primary">预览完整交接包</button><p class="human-note">样稿不会发送交接消息，也不会把“生成交接包”记作“交接完成”。</p></aside></div>`;document.querySelectorAll('[data-handoff-task]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.handoffTask;state.stage='all';state.status='all';state.query='';location.hash='#work';});$('#previewHandoff').onclick=()=>dialog('完整交接包 · '+projectLabel,`<p>合成数据；完整保留当前筛选下 ${rows.length} 项记录，未截断正文。</p><pre>${esc(handoffText(rows))}</pre>`);}
function handoffText(rows){return JSON.stringify({synthetic:true,as_of:DEMO_NOW,scope:{project:state.project,view:state.view,role:state.role},tasks:rows.map(t=>({...t,local_handoff_draft:state.notes.get(t.id)??null})),references:state.references.filter(r=>state.project==='all'||r.receiver===state.project),business_acceptance:'未发生，本样稿无确认能力'},null,2);}
let routeInitialized=false;
function route(){const page=location.hash.slice(1);state.page=['work','assets','handoff'].includes(page)?page:'work';render(false);if(routeInitialized)$('#main').focus({preventScroll:true});routeInitialized=true;}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;syncScope();render();});
$('#projectFilter').onchange=e=>{state.project=e.target.value;state.assetQuery='';state.stage='all';render();};
$('#roleFilter').onchange=e=>{state.role=e.target.value;render();};
$('#closeDialog').onclick=()=>$('#previewDialog').close();
$('#previewDialog').addEventListener('click',e=>{if(e.target===$('#previewDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#resetDemo').onclick=()=>{state.references=[];state.notes.clear();state.assetQuery='';state.receiver='customer';state.selected='QH-142';resetFilters();notify('筛选与本页草稿已重置；没有生产数据变化。');};
$('#showModel').onclick=()=>dialog('数据口径与接入边界',`<p>本样稿使用 ${tasks.length} 项合成任务、${assets.length} 项合成资产。所有计数由这些记录和当前筛选实时计算，不代表实际团队绩效。</p><ul><li>阶段是面向用户的展示分类，不修改现有任务状态迁移。</li><li>等待时长使用明确的合成字段；0 表示没有等待事件，未知表示没有等待起点。实际接入不能用任务更新时间代替等待起点。</li><li>角色视角与“与我相关”仅为筛选，没有增加任何授权。真实写操作仍需个人身份及后端权限检查。</li><li>下一责任人和受阻原因需要明确的责任与等待记录，不能由模型猜成事实。</li><li>技术检查、人工复核、客户验收分别记录。此样稿不提供任何确认或关单动作。</li><li>来源项目固定版本与接收项目的适用性、共享授权、人工决定相互独立。</li></ul><p>现有工作台、团队、记忆、资产与评审 API 可作为接入基础；组织层的等待事件和接力记录需要后续设计与实现。没有统计 ROI 或自动化成功率。</p><p>独立模型评审的真实执行器启动尚未验证可用（Claude 能力检查超时）；本样稿不表示模型能力已上线。</p>`);
window.addEventListener('hashchange',route);
syncScope();route();
